/** 24dp square, matching the viewport, so an icon drawn without a size modifier is the design's. */
private val IconSize = 24.dp

/** The spec's weight. Heroicons ships 1.5; the design draws 1.6, and the design wins. */
private const val STROKE_WIDTH = 1.6f

/**
 * Outline artwork carries no fill and no colour of its own. The stroke is black only so there is
 * something to recolour: `Icon` paints a tint over the whole vector, and that is what makes the
 * design's `currentColor` true here.
 */
private fun heroicon(name: String, vararg paths: String): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = IconSize,
        defaultHeight = IconSize,
        viewportWidth = 24f,
        viewportHeight = 24f,
    ).apply {
        paths.forEach { data ->
            addPath(
                pathData = addPathNodes(data),
                fill = null,
                stroke = SolidColor(Color.Black),
                strokeLineWidth = STROKE_WIDTH,
                strokeLineCap = StrokeCap.Round,
                strokeLineJoin = StrokeJoin.Round,
            )
        }
    }.build()
